<?php require_once dirname(__DIR__, 2).'/includes/config.php';$title='หัวข้อคะแนน Office';$p=db();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['edit'])){$p->prepare('UPDATE office_criteria SET max_score=?,description=? WHERE id=?')->execute([(float)$_POST['max_score'],trim($_POST['description']),(int)$_POST['id']]);go('Page/admin/office_criteria.php');}$rows=$p->query('SELECT * FROM office_criteria WHERE active=1 ORDER BY item_no')->fetchAll();require FIVE_S_ROOT.'/includes/header.php';?><div class="card p-5 mb-5"><h1 class="text-2xl font-black">🏢 หัวข้อคะแนน Office</h1><p class="text-slate-500">อ้างอิงแบบตรวจประเมินมาตรฐานกิจกรรม 5 ส. (OFFICE) จำนวน 21 ข้อ คะแนนเต็มรวม 50 คะแนน</p></div><div class="card p-5"><div class="overflow-x-auto"><table id="tbl" class="display w-full"><thead><tr><th>ข้อ</th><th>หัวข้อประเมินมาตรฐาน</th><th>เต็ม</th><th>แก้ไข</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['item_no']?></td><td><?=h($r['description'])?></td><td><?=$r['max_score']?></td><td><button class="text-blue-600 font-bold" onclick='editC(<?=json_encode($r,JSON_UNESCAPED_UNICODE)?>)'>แก้ไข</button></td></tr><?php endforeach;?></tbody></table></div></div><div id="box" class="hidden fixed inset-0 bg-black/40 items-center justify-center p-4"><form method="post" class="bg-white rounded-2xl p-6 w-full max-w-3xl space-y-3"><input type="hidden" name="edit" value="1"><input type="hidden" name="id" id="cid"><label>คะแนนเต็ม</label><input name="max_score" id="cmax" class="w-full border rounded-xl p-3"><label>หัวข้อประเมิน</label><textarea name="description" id="cdesc" rows="7" class="w-full border rounded-xl p-3"></textarea><div class="flex gap-2"><button class="bg-blue-600 text-white px-5 py-2 rounded-xl">บันทึก</button><button type="button" onclick="box.classList.add('hidden')" class="border px-5 py-2 rounded-xl">ยกเลิก</button></div></form></div><script>function editC(x){cid.value=x.id;cmax.value=x.max_score;cdesc.value=x.description;box.classList.remove('hidden');box.classList.add('flex')}$(function(){$('#tbl').DataTable({pageLength:25,scrollX:true,language:{search:'ค้นหา:',lengthMenu:'แสดง _MENU_',paginate:{next:'ถัดไป',previous:'ก่อนหน้า'}}})})</script><?php require FIVE_S_ROOT.'/includes/footer.php';?>